mapper.select:
SELECT id, title, content, category, distilled, created_at
FROM work_log
WHERE user_id = #{userId} AND id = #{id}

SELECT id, title, content, category, distilled, created_at
FROM work_log
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE work_log
SET distilled = 1, updated_at = #{updatedAt}
WHERE id = #{id} AND user_id = #{userId} AND distilled = 0
